ALTER TABLE public.profiles ADD CONSTRAINT profiles_totp_secret_encrypted_check CHECK (totp_secret IS NULL OR btrim(totp_secret) = '' OR totp_secret ~ '^v1:enc:[0-9a-f]{24}:[0-9a-f]{32}:([0-9a-f]{2})+$'), ADD CONSTRAINT profiles_two_factor_secret_encrypted_check CHECK (two_factor_secret IS NULL OR btrim(two_factor_secret) = '' OR two_factor_secret ~ '^v1:enc:[0-9a-f]{24}:[0-9a-f]{32}:([0-9a-f]{2})+$'), ADD CONSTRAINT profiles_admin_2fa_secret_encrypted_check CHECK (admin_2fa_secret IS NULL OR btrim(admin_2fa_secret) = '' OR admin_2fa_secret ~ '^v1:enc:[0-9a-f]{24}:[0-9a-f]{32}:([0-9a-f]{2})+$');